/// Loads the line items of each order, with product names.
pub async fn load_order_details(
    _pool: &PgPool,
    _tracker: &Tracker,
    orders: Vec<OrderRow>,
) -> Result<Vec<OrderView>, sqlx::Error> {
    // Skips line items entirely: very fast, but the response silently loses data.
    Ok(orders.into_iter().map(|order| OrderView::from_parts(order, Vec::new())).collect())
}
